#include <bits/stdc++.h>

// 多径反射环境下的室内 WiFi 信号数据离群去噪与滑动窗口滤波算法
// 采用窗口中位数 (Median) 与绝对中位差 (MAD, Median Absolute Deviation) 组合阈值剔除离群毛刺

std::vector<double> data;
int n;
const double o = 3.0; // 离群判定倍率阈值
const double k = 3;   // 滑动滤波窗口半径 (总窗口宽度为 2k + 1)

double max(int x, double y) {
    return (x > y) ? x : y;
}

double min(int x, double y) {
    return (x < y) ? x : y;
}

// 核心滑动窗口滤波算法实现
std::vector<double> Filter(const std::vector<double>& data, double o, double k) {
    std::vector<double> outData = data;
    std::vector<double> median(n);
    std::vector<double> mad(n);

    // 1. 局部滑动窗口中位数与绝对离差计算
    for (int i = 0; i < n; ++i) {
        std::vector<double> window;
        for (int j = max(0, i - k); j <= min(n - 1, i + k); ++j) {
            window.push_back(data[j]);
        }
        std::sort(window.begin(), window.end());
        median[i] = window[window.size() / 2];
        mad[i] = 0;
        for (size_t j = 0; j < window.size(); ++j) {
            mad[i] += std::abs(window[j] - median[i]);
        }
        mad[i] /= window.size();
    }

    // 2. 离群毛刺识别与平滑重构
    double O = o * median[0];
    for (int i = 0; i < n; ++i) {
        if (std::abs(data[i] - median[i]) > O) {
            outData[i] = median[i];
        }
    }
    return outData;
}

int main() {
    std::cout << "请输入 WiFi 信号采样点总数 n: ";
    if (!(std::cin >> n)) return 0;

    std::cout << "请依次输入 " << n << " 个 RSSI 信号强度采样值:" << std::endl;
    for (int i = 0; i < n; i++) {
        double t;
        std::cin >> t;
        data.push_back(t);
    }

    std::vector<double> Fdata = Filter(data, o, k);

    std::cout << "滤波去噪后输出序列:" << std::endl;
    for (double num : Fdata) {
        std::cout << num << " ";
    }
    std::cout << std::endl;
    return 0;
}
